const withLog = (name, fn) => (...args) => {
  console.log('>' + name);
  const r = fn(...args);
  console.log('<' + name);
  return r;
};
const add = withLog('add', (a, b) => a + b);
const twice = withLog('twice', x => add(x, x));
console.log(twice(3));

function memoize(fn) {
  const cache = new Map();
  return n => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}
let calls = 0;
const square = memoize(n => { calls++; return n * n; });
square(4); square(4); square(5);
console.log(calls, square(5));

